      title: SUPPLEMENT_FACTS_DEFAULT_DRAFT.title,
      servingSize: SUPPLEMENT_FACTS_DEFAULT_DRAFT.servingSize,
      servingsPerContainer: SUPPLEMENT_FACTS_DEFAULT_DRAFT.servingsPerContainer,
